export const VALUES=[1,2,3,4,8,12,50];
export const FREQUENCIES=[32.3,23.75,17.1,12.35,6.65,2.85,5];
export function chooseKind(randomValue){let limit=0;const roll=randomValue*100;for(let i=0;i<FREQUENCIES.length;i++){limit+=FREQUENCIES[i];if(roll<limit)return i;}return FREQUENCIES.length-1;}
export class GardenGame{
 constructor(random=Math.random){this.random=random;this.resize(1000,700);this.state='ready';this.score=0;this.lives=3;this.time=0;this.items=[];this.effects=[];this.player=.5;this.previousPlayer=.5;this.cry=0;this.pausedFrom=null;this.spawnIn=1;this.thrower={x:.2,y:.15,pose:0};this.onEvent=()=>{};}
 resize(w,h,portrait=w/h<1){const ow=this.w||w,oh=this.h||h;this.w=w;this.h=h;for(const i of this.items||[]){i.x*=w/ow;i.y*=h/oh;i.vx*=w/ow;i.vy*=h/oh;i.g*=h/oh;}this.mobile=portrait;this.playerHeight=h*(this.mobile?.22:.265);this.catchY=h-18-this.playerHeight*.62;this.basketHalf=this.playerHeight*.145;}
 start(){this.state='playing';this.score=0;this.lives=3;this.time=0;this.items=[];this.effects=[];this.player=.5;this.previousPlayer=.5;this.cry=0;this.pausedFrom=null;this.spawnIn=.8;this.onEvent('start');}
 pause(){if(this.state==='playing'||this.state==='hurt'){this.pausedFrom=this.state;this.state='paused';this.onEvent('pause');}}
 resume(){if(this.state==='paused'){this.state=this.pausedFrom||'playing';this.pausedFrom=null;this.onEvent('resume');}}
 spawn(){const kind=chooseKind(this.random());const side=this.random();const x=side<.30?.10:side>.7?.90:.18+this.random()*.64;const y=side<.30||side>.7?.19:.125;const target=.09+this.random()*.82;const duration=Math.max(1.55,3.7-this.time*.017);const gravity=this.h*.14;const vy=(this.catchY-y*this.h-.5*gravity*duration*duration)/duration;this.thrower={x,y,pose:.5};this.items.push({kind,x:x*this.w,y:y*this.h,vx:(target-x)*this.w/duration,vy,g:gravity,spin:this.random()*6,age:0});}
 update(dt,input=0,target=null){if(this.state==='hurt'){this.cry=Math.max(0,this.cry-Math.max(0,dt));if(this.cry<1e-9){this.cry=0;this.previousPlayer=this.player;this.state=this.lives>0?'playing':'over';if(this.state==='over')this.items=[];this.onEvent(this.state==='over'?'over':'recover');}return;}if(this.state!=='playing')return;dt=Math.min(dt,.05);this.time+=dt;this.cry=Math.max(0,this.cry-dt);this.thrower.pose=Math.max(0,this.thrower.pose-dt);this.previousPlayer=this.player;const speed=this.mobile?.70:.56;if(target!==null){const d=target-this.player;this.player+=Math.sign(d)*Math.min(Math.abs(d),speed*dt*1.4);}else this.player+=input*speed*dt;this.player=Math.max(.065,Math.min(.935,this.player));this.spawnIn-=dt;if(this.spawnIn<=0){this.spawn();this.spawnIn=Math.max(.64,1.5-this.time*.009);}
  const kept=[];for(let index=0;index<this.items.length;index++){const i=this.items[index];const oldY=i.y,oldX=i.x;i.age+=dt;i.x+=i.vx*dt;i.y+=i.vy*dt+.5*i.g*dt*dt;i.vy+=i.g*dt;
   if(oldY<=this.catchY&&i.y>=this.catchY){const f=(this.catchY-oldY)/(i.y-oldY||1),crossX=oldX+(i.x-oldX)*f,playerX=(this.previousPlayer+(this.player-this.previousPlayer)*f)*this.w;const radius=Math.min(this.w,this.h)*.018;if(Math.abs(crossX-playerX)<=this.basketHalf+radius*.55){this.score+=VALUES[i.kind];this.effects.push({x:crossX,y:this.catchY,kind:'catch',value:VALUES[i.kind],life:1});this.onEvent('catch',VALUES[i.kind]);continue;}}
   if(i.y>this.h-12){this.lives=Math.max(0,this.lives-1);this.cry=2;this.state='hurt';this.previousPlayer=this.player;this.effects.push({x:i.x,y:this.h-20,kind:'miss',life:.7});this.items=kept.concat(this.items.slice(index+1));this.onEvent('miss');return;}kept.push(i);
  }if(this.state!=='over')this.items=kept;this.effects=this.effects.filter(e=>(e.life-=dt)>0);
 }
}
